python - <<'PY'
import duckdb,yaml
c=duckdb.connect('qualtrics.duckdb',read_only=True); y=yaml.safe_load(open('docs/data_contract.yaml'))
for layer,arr,schema in [('staging',y['staging_contract']['tables'],'staging'),('intermediate',y['modeling_spec']['intermediate_models'],'intermediate'),('marts',y['modeling_spec']['marts_models'],'mart')]:
 for m in arr:
  n=m['name']; got=[x[0] for x in c.execute(f'describe {schema}.{n}').fetchall()]; expected=[x['name'] for x in m['columns']]
  if got!=expected: print(n,'missing',set(expected)-set(got),'extra',set(got)-set(expected),'order',got==expected)
print('total tables', c.execute("select count(*) from information_schema.tables where table_schema in ('staging','intermediate','mart')").fetchone()[0])
